// Generates src/api/types.gen.ts from the backend OpenAPI document.
// Usage: npm run gen:api   (backend must be running; reads OPENAPI_URL from .env if present)
import { mkdir, writeFile } from 'node:fs/promises';
import path from 'node:path';
import openapiTS, { astToString } from 'openapi-typescript';

const DEFAULT_OPENAPI_URL = 'http://localhost:8080/v3/api-docs';
const url = process.env.OPENAPI_URL?.trim() || DEFAULT_OPENAPI_URL;
const outFile = path.resolve(import.meta.dirname, '..', 'src', 'api', 'types.gen.ts');
const header =
  '/* eslint-disable */\n' +
  '// GENERATED by `npm run gen:api` from the backend OpenAPI document. Do not edit by hand.\n\n';

try {
  const ast = await openapiTS(new URL(url));
  await mkdir(path.dirname(outFile), { recursive: true });
  await writeFile(outFile, header + astToString(ast), 'utf8');
  console.log(`Đã sinh ${path.relative(process.cwd(), outFile)} từ ${url}`);
} catch (error) {
  const reason = error instanceof Error ? error.message : String(error);
  console.error(`Không lấy được OpenAPI từ ${url}. Backend đã chạy chưa? (${reason})`);
  process.exitCode = 1;
}
